import React, { useEffect, useState } from "react";
import BudgetSummary from "./BudgetSummary";
import BudgetProgress from "./BudgetProgress";
import CategoryBudget from "./CategoryBudget";
import DailyLimit from "./DailyLimit";
import BudgetAlerts from "./BudgetAlerts";
import BudgetHistory from "./BudgetHistory";

import { getIncome } from "../../api/incomeApi";
import { getExpenses } from "../../api/expenseApi";

const BudgetPlanner = () => {
  const [incomeList, setIncomeList] = useState([]);
  const [expenseList, setExpenseList] = useState([]);

  // Temporary Goal (Later we'll store this in MongoDB)
  const [goalAmount] = useState(150000);

  const fetchData = async () => {
    try {
      const [incomeRes, expenseRes] = await Promise.all([
        getIncome(),
        getExpenses(),
      ]);

      console.log("Income API:", incomeRes.data);
      console.log("Expense API:", expenseRes.data);

      // Income
      const incomes = Array.isArray(incomeRes.data)
        ? incomeRes.data
        : incomeRes.data.incomes || [];

      // Expense
      const expenses = Array.isArray(expenseRes.data)
        ? expenseRes.data
        : expenseRes.data.expenses || [];

      setIncomeList(incomes);
      setExpenseList(expenses);

      console.log("Income List:", incomes);
      console.log("Expense List:", expenses);
    } catch (err) {
      console.error("Budget Planner Error:", err);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const totalIncome = incomeList.reduce(
    (sum, item) => sum + Number(item.amount || 0),
    0
  );

  const totalExpense = expenseList.reduce(
    (sum, item) => sum + Number(item.amount || 0),
    0
  );

  const currentSavings = totalIncome - totalExpense;

  const remainingAmount = Math.max(
    goalAmount - currentSavings,
    0
  );

  return (
    <div className="min-h-screen bg-slate-900 p-8">
      <h1 className="text-4xl font-bold text-white mb-8">
        🎯 Goal Planner
      </h1>

      <BudgetSummary
        goalAmount={goalAmount}
        currentSavings={currentSavings}
        remainingAmount={remainingAmount}
      />

      <BudgetProgress
        goalAmount={goalAmount}
        currentSavings={currentSavings}
      />

      <CategoryBudget
        expenses={expenseList}
      />

      <DailyLimit
        goalAmount={goalAmount}
        currentSavings={currentSavings}
      />

      <BudgetAlerts
        goalAmount={goalAmount}
        currentSavings={currentSavings}
      />

      <BudgetHistory />
    </div>
  );
};

export default BudgetPlanner;